<script setup>
import {ref} from 'vue'
import {api} from '../../services/api.js'
const props=defineProps({connectionId:String})
const form=ref({sourceIp:'',destinationIp:'',sourcePort:50000,destinationPort:443,protocol:'TCP'}),result=ref(null),error=ref(''),busy=ref(false)
async function assess(){busy.value=true;error.value='';result.value=null;try{result.value=await api('/mapping/cloud-path?'+new URLSearchParams({connectionId:props.connectionId,...form.value}))}catch(e){error.value=e.message}finally{busy.value=false}}
</script>
<template><details class="cloud-path"><summary>Assess configured cloud path</summary><p>Evaluate retained NSG and route configuration for a new flow. This does not test connectivity or change Azure resources.</p><form @submit.prevent="assess"><label>Source IP<input v-model.trim="form.sourceIp" required></label><label>Destination IP<input v-model.trim="form.destinationIp" required></label><label>Source port<input v-model.number="form.sourcePort" type="number" min="0" max="65535" required></label><label>Destination port<input v-model.number="form.destinationPort" type="number" min="0" max="65535" required></label><label>Protocol<select v-model="form.protocol"><option>TCP</option><option>UDP</option></select></label><button class="button secondary" :disabled="busy||!connectionId">{{busy?'Assessing…':'Assess configuration'}}</button></form><p v-if="error" class="error-msg" role="alert">{{error}}</p><template v-if="result"><p>Configuration: <strong>{{result.configurationDecision}}</strong> · Reachability: indeterminate</p><ul><li v-for="(s,i) in result.steps" :key="i">{{s.direction}} {{s.level}} · {{s.decision}}<span v-if="s.rule"> · {{s.rule}} (priority {{s.priority}})</span> — {{s.reason}}</li><li v-for="gap in result.gaps" :key="gap">{{gap}}</li></ul><p v-for="limit in result.limitations" :key="limit" class="muted">{{limit}}</p></template></details></template>
<style scoped>.cloud-path{margin:18px 0;overflow-wrap:anywhere}form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}label{display:grid;gap:6px}input,select{min-width:0;width:100%;box-sizing:border-box}@media(max-width:760px){form{grid-template-columns:1fr}}</style>
